// Read Sarvam's post call payload and reduce it to the one thing that matters: did the
// shopkeeper agree. Sarvam returns collected output variables from the agent, and the
// exact envelope varies by agent version, so every field is looked for in a few likely
// places rather than assumed.
//
// The discount offer response variable is the one the voice agent is configured to
// collect when it reads the offer out. It is treated as the merchant modifying the offer,
// not as a number the agent invented: the backend still owns every figure.

const body = $json.body || $json;
const variables = body.output_variables || body.outputVariables || body.variables || {};
const transcript = body.transcript || body.conversation_transcript || '';

const approvalRaw = String(
  variables.approved
  ?? variables.approval
  ?? variables.merchant_approved
  ?? body.approved
  ?? ''
).trim().toLowerCase();

const discountOfferResponse =
  variables.discount_offer_response
  ?? variables.discountOfferResponse
  ?? variables.offer_response
  ?? null;

const callStatus = String(body.status || body.call_status || '').trim().toLowerCase();

const YES = ['haan', 'ha', 'yes', 'true', 'approved', 'accept', 'accepted', 'bhej do'];
const NO = ['nahi', 'nahin', 'no', 'false', 'declined', 'reject', 'rejected', 'mat bhejo'];

let outcome = 'no_answer';
if (['no-answer', 'no_answer', 'noanswer', 'busy', 'failed', 'missed'].includes(callStatus)) {
  outcome = 'no_answer';
} else if (YES.some((word) => approvalRaw.includes(word))) {
  outcome = 'approved';
} else if (NO.some((word) => approvalRaw.includes(word))) {
  outcome = 'declined';
}

return {
  json: {
    call_id: body.call_id || body.callId || body.conversation_id || '',
    merchant_id: body.merchant_id || variables.merchant_id || 'tea_stall_01',
    outcome,
    transcript,
    modifications: {
      discount_offer_response: discountOfferResponse,
      raw_approval: approvalRaw,
      call_status: callStatus,
    },
  },
};
